package com.canteen.management.controller;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.web.bind.annotation.*;import jakarta.validation.Valid;import com.canteen.management.dto.LoginRequest;import com.canteen.management.dto.LoginResponse;import com.canteen.management.dto.StudentRequest;import com.canteen.management.dto.StudentResponse;import com.canteen.management.service.StudentService;import com.canteen.management.dto.ForgotPasswordRequest;import com.canteen.management.dto.VerifyOtpRequest;import com.canteen.management.dto.ResetPasswordRequest;import com.canteen.management.service.EmailService;import com.canteen.management.service.OtpService;import com.canteen.management.repository.StudentRepository;import com.canteen.management.entity.Student;import com.canteen.management.dto.UpdateProfileRequest;import com.canteen.management.dto.UpdateProfileResponse;@RestController@RequestMapping("/student")public class StudentController {    @Autowired    private StudentService studentService;    @Autowired    private OtpService otpService;    @Autowired    private EmailService emailService;    @Autowired    private StudentRepository studentRepository;    @PostMapping("/register")    public StudentResponse registerStudent(@Valid @RequestBody StudentRequest studentRequest) {        return studentService.saveStudent(studentRequest);    }    @PutMapping("/profile")    public UpdateProfileResponse updateProfile(            @RequestBody UpdateProfileRequest request) {        return studentService.updateProfile(request);    }    @PostMapping("/login")    public LoginResponse login(@RequestBody LoginRequest loginRequest) {        return studentService.login(loginRequest);    }    @GetMapping("/{studentId}")    public StudentResponse getStudentByStudentId(@PathVariable String studentId) {        return studentService.getStudentByStudentId(studentId);    }    @PostMapping("/forgot-password")    public String forgotPassword(            @RequestBody ForgotPasswordRequest request) {        Student student = studentRepository                .findByEmail(request.getEmail());        if (student == null) {            return "Email Not Registered";        }        String otp = otpService.generateOtp(request.getEmail());        emailService.sendOtp(                request.getEmail(),                otp        );        return "OTP Sent Successfully";    }    @PostMapping("/verify-otp")    public String verifyOtp(            @RequestBody VerifyOtpRequest request) {        boolean valid = otpService.verifyOtp(                request.getEmail(),                request.getOtp()        );        if (valid) {            return "OTP Verified";        }        return "Invalid OTP";    }    @PostMapping("/reset-password")    public String resetPassword(            @RequestBody ResetPasswordRequest request) {        Student student = studentRepository                .findByEmail(request.getEmail());        if (student == null) {            return "User Not Found";        }        student.setPassword(request.getNewPassword());        studentRepository.save(student);        return "Password Reset Successfully";    }}